ccessoires","s":"celio-ceinture","n":"Ceinture en cuir","cen":"Accessories","en":"Leather belt","v":[{"l":"Standard","k":null,"p":null,"u":"piece","q":0}],"i":[]}]';
begin
  for r in select * from jsonb_array_elements(data) loop
    select id into b from public.brands where slug = r ->> 'b';
    select count(*) into cpos from public.categories where brand_id = b;
    insert into public.categories (brand_id, slug, name_fr, name_en, position)
    values (b, r ->> 'c', r ->> 'cn', r ->> 'cen', cpos)
    on conflict (brand_id, slug) do update set name_fr = excluded.name_fr
    returning id into c;

    insert into public.products (brand_id, category_id, slug, name_fr, name_en, description_fr, description_en, base_price, tag)
    values (b, c, r ->> 's', r ->> 'n', r ->> 'en', r ->> 'd', r ->> 'den',
            (select min((x ->> 'p')::numeric) from jsonb_array_elements(r -> 'v') x), r ->> 't')
    on conflict (slug) do nothing
    returning id into pid;
    continue when pid is null;

    i := 0;
    for v in select * from jsonb_array_elements(r -> 'v') loop
      insert into public.product_variants (product_id, label, sku_eshopaid, price, unit, stock, is_default, position)
      values (pid, v ->> 'l', v ->> 'k', (v ->> 'p')::numeric, (v ->> 'u')::public.sale_unit, (v ->> 'q')::int, i = 0, i);
      i := i + 1;
    end loop;

    i := 0;
    for img in select * from jsonb_array_elements_text(r -> 'i') loop
      insert into public.product_images (product_id, url, alt, position) values (pid, img, r ->> 'n', i);
      i := i + 1;
    end loop;
  end loop;
end $seed$;
